-- Deal integrity, ownership, snapshot and controlled delete.
create or replace function public.deal_commercial_lock_guard() returns trigger language plpgsql set search_path=public as $$begin if current_user not in ('postgres','service_role') and old.status in ('approved','completed','cancelled') then if new.customer_id is distinct from old.customer_id or new.supplier_id is distinct from old.supplier_id or new.amount is distinct from old.amount or new.buy_currency is distinct from old.buy_currency or new.sell_currency is distinct from old.sell_currency or new.buy_rate is distinct from old.buy_rate or new.sell_rate is distinct from old.sell_rate or new.buy_price is distinct from old.buy_price or new.sell_price is distinct from old.sell_price or new.commodity is distinct from old.commodity or new.quantity is distinct from old.quantity or new.unit is distinct from old.unit or new.origin_country is distinct from old.origin_country or new.destination_country is distinct from old.destination_country or new.incoterm is distinct from old.incoterm or new.quotation_id is distinct from old.quotation_id or new.opportunity_id is distinct from old.opportunity_id then raise exception 'Approved, completed or cancelled deals are commercially locked. Use a controlled amendment workflow.';end if;end if;return new;end$$;
drop trigger if exists trg_deal_commercial_lock_guard on public.deals;create trigger trg_deal_commercial_lock_guard before update on public.deals for each row execute function public.deal_commercial_lock_guard();
create or replace function public.deal_assign_owner_v1(p_deal_id uuid,p_owner_id uuid,p_reason text default null) returns public.deals language plpgsql security definer set search_path=public as $$declare r text:=public.deal_current_role();d public.deals;o uuid;begin if r not in ('admin','ceo','manager','dealer') then raise exception 'Owner assignment is not permitted for this role.';end if;if p_owner_id is null or not exists(select 1 from public.profiles where id=p_owner_id and active=true) then raise exception 'Selected owner is not an active user.';end if;if r='dealer' and p_owner_id is distinct from auth.uid() then raise exception 'Dealer users may only assign a deal to themselves.';end if;select * into d from public.deals where id=p_deal_id for update;if not found then raise exception 'Deal not found.';end if;if d.status in ('completed','cancelled') then raise exception 'Closed deals cannot be reassigned.';end if;o:=d.dealer_id;update public.deals set dealer_id=p_owner_id,updated_at=now() where id=p_deal_id returning * into d;insert into public.deal_events(deal_id,event_type,from_value,to_value,reason,performed_by) values(d.id,'owner_changed',o::text,p_owner_id::text,nullif(trim(coalesce(p_reason,'')),''),auth.uid());return d;end$$;
create or replace function public.deal_delete_v1(p_deal_id uuid,p_reason text) returns boolean language plpgsql security definer set search_path=public as $$declare d public.deals;deps int;begin if public.deal_current_role() not in ('admin','ceo') then raise exception 'Only Admin or CEO can delete a deal.';end if;if length(trim(coalesce(p_reason,'')))<5 then raise exception 'Deletion reason must contain at least 5 characters.';end if;select * into d from public.deals where id=p_deal_id for update;if not found then raise exception 'Deal not found.';end if;if d.status not in ('draft','cancelled') then raise exception 'Only draft or cancelled deals can be deleted.';end if;select (select count(*) from public.shipments where deal_id=p_deal_id)+(select count(*) from public.invoices where deal_id=p_deal_id)+(select count(*) from public.payments where deal_id=p_deal_id)+(select count(*) from public.approvals where entity_type='deal' and entity_id=p_deal_id) into deps;if deps>0 then raise exception 'Deal has operational, financial or approval history and cannot be deleted.';end if;delete from public.deal_events where deal_id=p_deal_id;delete from public.deals where id=p_deal_id;return true;end$$;
drop policy if exists "Admins can delete deals" on public.deals;drop policy if exists deals_delete_roles on public.deals;drop policy if exists "Admins and managers can update all deals" on public.deals;create policy "Controllers can update unlocked deals" on public.deals for update to authenticated using(public.deal_current_role() in ('admin','ceo','manager')) with check(public.deal_current_role() in ('admin','ceo','manager'));
revoke all on function public.deal_assign_owner_v1(uuid,uuid,text) from public,anon;revoke all on function public.deal_delete_v1(uuid,text) from public,anon;grant execute on function public.deal_assign_owner_v1(uuid,uuid,text),public.deal_delete_v1(uuid,text) to authenticated,service_role;
